:"2nd"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 2","title":"Exercise-Based Fitness Activities","units":2.0,"year_level":1,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"NSTP 2","title":"CWTS 2","units":3.0,"year_level":1,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"GE 6","title":"Science, Technology and Society","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"GE 7","title":"Ethics","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"GEE 2","title":"Living in the I.T Era","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"ELECTIVE 1","title":"Movement Education","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 3","title":"Biomechanics","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 05","title":"Anatomy of Human Movement and Performance","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 06","title":"Musculoskeletal fitness training methods","units":3.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 3","title":"Dance","units":2.0,"year_level":2,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"GE 8","title":"Life and Works of Rizal","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"GE 9","title":"The Contemporary World","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"GEE 3","title":"Reading Visual Arts","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"ELECTIVE 2","title":"Stress Management","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 4","title":"Ergogenic and Healthy Eating in Exercise and Sports","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 5","title":"Assessment of Fitness and Sports Performance","units":3.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 4","title":"Sports","units":2.0,"year_level":2,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 07","title":"Sports and Exercise Psychology","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"ELECTIVE 3","title":"Fundamentals of Management Practice","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 08","title":"Individual and Sports I (Any Racket Sports)","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 09","title":"Cardiorespiratory Fitness/ Aerobic Training Methods","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 10","title":"Outdoor and Adventure Education","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"RESEARCH 1","title":"Methods of Research","units":3.0,"year_level":3,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 11","title":"Swimming and Aquatics","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"SPEC FSC 12","title":"Team Sports 1 (Basketball, Volleyball,)","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 6","title":"Strength and Conditioning","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 7","title":"Exercise Prescription and Programming","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"PROF COURSE 8","title":"Prevention and Management of Exercise and Sports-Related injuries","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"RESEARCH 2","title":"Applied Research in Exercise and Sports","units":3.0,"year_level":3,"semester":"2nd"},{"program_code":"BSESS-FSC","course_code":"INTERNSHIP 1","title":"Professional Preparation","units":6.0,"year_level":4,"semester":"1st"},{"program_code":"BSESS-FSC","course_code":"INTERNSHIP 2","title":"Industry Immersion","units":6.0,"year_level":4,"semester":"2nd"}]$course_json$::jsonb;
  v_prereqs jsonb := $prereq_json$[{"program_code":"BSCrim","course_code":"PATHFIT 2","prerequisite_code":"PATHFIT 1"},{"program_code":"BSCrim","course_code":"NSTP 2","prerequisite_code":"NSTP 1"},{"program_code":"BSCrim","course_code":"PATHFIT 3","prerequisite_code":"PATHFIT 2"},{"program_code":"BSCrim","course_code":"CFLM-2","prerequisite_code":"CFLM-1"},{"program_code":"BSCrim","course_code":"PATHFIT 4","prerequisite_code":"PATHFIT 3"},{"program_code":"BSCrim","course_code":"CLJ 4","prerequisite_code":"CLJ 2"},{"program_code":"BSCrim","course_code":"CLJ 4","prerequisite_code":"CLJ 3"},{"program_code":"BSCrim","course_code":"CLJ 5","prerequisite_code":"CLJ 2"},{"program_code":"BSCrim","course_code":"CLJ 5","prerequisite_code":"CLJ 3"},{"program_code":"BSCrim","course_code":"CDI 8","prerequisite_code":"CDI 5"},{"program_code":"BSCrim","course_code":"CLJ 6","prerequisite_code":"CLJ 5"},{"program_code":"BSCrim","course_code":"CRIMINOLOGY 8","prerequisite_code":"CRIMINOLOGY 7"},{"program_code":"BSCrim","course_code":"CRIMINOLOGY PRACTICUM 2","prerequisite_code":"CRIMINOLOGY PRACTICUM 1"},{"program_code":"BSCrim","course_code":"CPEP 2","prerequisite_code":"CPEP 1"},{"program_code":"BTLEd-ICT","course_code":"PATHFIT 2","prerequisite_code":"PATHFIT 1"},{"program_code":"BTLEd-ICT","course_code":"NSTP 2","prerequisite_code":"NSTP 1"},{"program_code":"BTLEd-ICT","course_code":"PATHFIT 3","prerequisite_code":"PATHFIT 2"},{"program_code":"BTLEd-ICT","course_code":"ICT 7","prerequisite_code":"ICT 3"},{"program_code":"BTLEd-ICT","course_code":"ICT 7","prerequisite_code":"ICT 6"},{"program_code":"BTLEd-ICT","course_code":"ICT 9","prerequisite_code":"ICT 1"},{"program_code":"BTLEd-ICT","course_code":"TLE 4","prerequisite_code":"TLE 1"},{"program_code":"BTLEd-ICT","course_code":"TLE 5","prerequisite_code":"TLE 2"},{"program_code":"BTLEd-ICT","course_code":"TLE 6","prerequisite_code":"TLE 3"},{"program_code":"BTLEd-ICT","course_code":"PATHFIT 4","prerequisite_code":"PATHFIT 3"},{"program_code":"BTLEd-ICT","course_code":"ICT 10","prerequisite_code":"ICT 8"},{"program_code":"BTLEd-ICT","course_code":"ELC","prerequisite_code":"FS 1"},{"program_code":"BTLEd-ICT","course_code":"ELC","prerequisite_code":"FS 2"},{"program_code":"BSESS-FSM","course_code":"PATHFIT 2","prerequisite_code":"PATHFIT 1"},{"program_code":"BSESS-FSM","course_code":"NSTP 2","prerequisite_code":"NSTP 1"},{"program_code":"BSESS-FSM","course_code":"PATHFIT 3","prerequisite_code":"PATHFIT 2"},{"program_code":"BSESS-FSM","course_code":"PATHFIT 4","prerequisite_code":"PATHFIT 3"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 2","prerequisite_code":"PATHFIT 1"},{"program_code":"BSESS-FSC","course_code":"NSTP 2","prerequisite_code":"NSTP 1"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 3","prerequisite_code":"PATHFIT 2"},{"program_code":"BSESS-FSC","course_code":"PATHFIT 4","prerequisite_code":"PATHFIT 3"}]$prereq_json$::jsonb;
  v_version_name constant text := 'AY 2026-2027 — Imported Word Curriculum (Review Required)';
  v_academic_year constant text := '2026-2027';
  p record;
  c record;
  e record;
  v_existing_course record;
  v_existing_item record;
  v_program_id uuid;
  v_version_id uuid;
  v_course_id uuid;
  v_item_id uuid;
  v_prerequisite_id uuid;
  v_name text;
  v_active boolean;
  v_status text;
BEGIN
  -- Validate the complete embedded dataset before making changes.
  IF jsonb_array_length(v_courses) <> 215 OR jsonb_array_length(v_prereqs) <> 35 THEN
    RAISE EXCEPTION 'Invalid embedded curriculum dataset; expected 215 courses and 35 prerequisites';
  END IF;
  IF EXISTS (
    SELECT 1 FROM jsonb_to_recordset(v_courses)
      AS x(program_code text,course_code text,title text,units numeric,year_level smallint,semester text)
    GROUP BY program_code,course_code HAVING count(*) > 1
  ) THEN
    RAISE EXCEPTION 'Duplicate program+course codes in import dataset';
  END IF;

  -- First ensure all four program records and unpublished curriculum versions exist.
  FOR p IN
    SELECT * FROM (VALUES
      ('BSCrim', 'BS Criminology'),
      ('BTLEd-ICT', 'BTLEd – Information and Communication Technology'),
      ('BSESS-FSM', 'BSESS – Fitness and Sports Management'),
      ('BSESS-FSC', 'BSESS – Fitness and Sports Coaching')
    ) AS t(code, name)
  LOOP
    SELECT id, name, active INTO v_program_id, v_name, v_active
    FROM public.picc_academic_programs WHERE code = p.code;
    IF FOUND THEN
      IF v_name <> p.name OR NOT v_active THEN
        RAISE EXCEPTION 'Program % has a different name or is inactive; review before import', p.code;
      END IF;
    ELSE
      INSERT INTO public.picc_academic_programs(code,name)
      VALUES (p.code,p.name) RETURNING id INTO v_program_id;
    END IF;

    INSERT INTO public.picc_curriculum_versions(program_id,version_name,effective_academic_year)
    VALUES (v_program_id,v_version_name,v_academic_year)
    ON CONFLICT (program_id,version_name) DO NOTHING;

    SELECT status INTO v_status
    FROM public.picc_curriculum_versions
    WHERE program_id=v_program_id AND version_name=v_version_name;
    IF v_status IS DISTINCT FROM 'draft' THEN
      RAISE EXCEPTION 'Curriculum for % is not a draft; no import modifications allowed', p.code;
    END IF;
  END LOOP;

  -- Import catalog subjects; reject collisions, conflicting existing values and archived records.
  FOR c IN
    SELECT * FROM jsonb_to_recordset(v_courses)
    AS x(program_code text,course_code text,title text,units numeric,year_level smallint,semester text)
  LOOP
    SELECT id INTO v_program_id FROM public.picc_academic_programs WHERE code=c.program_code;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing program %', c.program_code; END IF;

    SELECT id, course_code, title, units, recommended_year, recommended_semester, active
    INTO v_existing_course
    FROM public.picc_academic_courses
    WHERE program_id=v_program_id
      AND regexp_replace(upper(course_code),'[^A-Z0-9]','','g') =
          regexp_replace(upper(c.course_code),'[^A-Z0-9]','','g')
    ORDER BY course_code
    LIMIT 1;

    IF FOUND THEN
      IF v_existing_course.course_code <> c.course_code
         OR lower(btrim(v_existing_course.title)) <> lower(btrim(c.title))
         OR v_existing_course.units <> c.units
         OR v_existing_course.recommended_year <> c.year_level
         OR v_existing_course.recommended_semester <> c.semester
         OR NOT v_existing_course.active THEN
        RAISE EXCEPTION 'Catalog collision for % / %. Review existing code, title, units, year and semester.', c.program_code, c.course_code;
      END IF;
      v_course_id := v_existing_course.id;
    ELSE
      INSERT INTO public.picc_academic_courses
        (program_id,course_code,title,units,recommended_year,recommended_semester)
      VALUES (v_program_id,c.course_code,c.title,c.units,c.year_level,c.semester)
      RETURNING id INTO v_course_id;
    END IF;

    SELECT id INTO v_version_id FROM public.picc_curriculum_versions
    WHERE program_id=v_program_id AND version_name=v_version_name;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing draft curriculum for %', c.program_code; END IF;

    INSERT INTO public.picc_curriculum_items
      (curriculum_id,program_id,course_id,year_level,semester,is_required)
    VALUES (v_version_id,v_program_id,v_course_id,c.year_level,c.semester,true)
    ON CONFLICT (curriculum_id,course_id) DO NOTHING;

    SELECT year_level,semester,is_required INTO v_existing_item
    FROM public.picc_curriculum_items WHERE curriculum_id=v_version_id AND course_id=v_course_id;
    IF NOT FOUND OR v_existing_item.year_level <> c.year_level
        OR v_existing_item.semester <> c.semester OR NOT v_existing_item.is_required THEN
      RAISE EXCEPTION 'Existing curriculum item differs from source for % / %', c.program_code, c.course_code;
    END IF;
  END LOOP;

  -- Add only resolved prerequisite relationships present in both imported curricula.
  -- Ambiguous/forward-looking prerequisites from Word files are intentionally omitted;
  -- review the warnings CSV before publishing.
  FOR e IN
    SELECT * FROM jsonb_to_recordset(v_prereqs)
      AS x(program_code text,course_code text,prerequisite_code text)
  LOOP
    -- Use distinct SQL aliases: p is also a PL/pgSQL RECORD variable.
    SELECT ap.id, cv.id INTO v_program_id, v_version_id
    FROM public.picc_academic_programs AS ap
    JOIN public.picc_curriculum_versions AS cv ON cv.program_id = ap.id
    WHERE ap.code = e.program_code AND cv.version_name = v_version_name;
    IF NOT FOUND THEN RAISE EXCEPTION 'Missing curriculum for prerequisite %', e.program_code; END IF;

    -- Avoid c: it is also the PL/pgSQL RECORD variable for course imports.
    SELECT ci.id INTO v_item_id
    FROM public.picc_curriculum_items AS ci
    JOIN public.picc_academic_courses AS catalog_course ON catalog_course.id = ci.course_id
    WHERE ci.curriculum_id = v_version_id AND catalog_course.course_code = e.course_code;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown target course % / %', e.program_code,e.course_code; END IF;

    SELECT ci.id INTO v_prerequisite_id
    FROM public.picc_curriculum_items AS ci
    JOIN public.picc_academic_courses AS catalog_course ON catalog_course.id = ci.course_id
    WHERE ci.curriculum_id = v_version_id AND catalog_course.course_code = e.prerequisite_code;
    IF NOT FOUND THEN RAISE EXCEPTION 'Unknown prerequisite course % / %', e.program_code,e.prerequisite_code; END IF;

    INSERT INTO public.picc_curriculum_prerequisites
      (curriculum_id,curriculum_item_id,prerequisite_item_id)
    VALUES (v_version_id,v_item_id,v_prerequisite_id)
    ON CONFLICT (curriculum_item_id,prerequisite_item_id) DO NOTHING;
  END LOOP;

  RAISE NOTICE 'PiCC import completed atomically: 215 course entries, 35 prerequisite relationships, 4 draft curricula. Verify counts below.';
END;
$picc_seed$;
